bool inside(HWND parent,HWND child){RECT a{},b{};GetClientRect(parent,&a);GetWindowRect(child,&b);MapWindowPoints(nullptr,parent,reinterpret_cast<POINT*>(&b),2);return IsWindowVisible(child)&&b.left>=0&&b.top>=0&&b.right<=a.right+1&&b.bottom<=a.bottom+1&&b.bottom>b.top;}
bool capture_dialog(HWND h,const std::filesystem::path& path){
    RedrawWindow(h,nullptr,nullptr,RDW_INVALIDATE|RDW_ERASE|RDW_ALLCHILDREN|RDW_UPDATENOW);
    RECT rect{};if(!GetWindowRect(h,&rect))return false;const int width=rect.right-rect.left,height=rect.bottom-rect.top;if(width<=0||height<=0||static_cast<int64_t>(width)*height>8000000)return false;
    const auto dc=GetWindowDC(h);if(!dc)return false;const auto memory=CreateCompatibleDC(dc);const auto bitmap_handle=CreateCompatibleBitmap(dc,width,height);if(!memory||!bitmap_handle){if(bitmap_handle)DeleteObject(bitmap_handle);if(memory)DeleteDC(memory);ReleaseDC(h,dc);return false;}
    const auto old=SelectObject(memory,bitmap_handle);RECT surface{0,0,width,height};FillRect(memory,&surface,GetSysColorBrush(COLOR_BTNFACE));
    SendMessageW(h,WM_PRINT,reinterpret_cast<WPARAM>(memory),PRF_CLIENT|PRF_NONCLIENT|PRF_CHILDREN|PRF_ERASEBKGND);GdiFlush();SelectObject(memory,old);
    bool saved=false;{Gdiplus::Bitmap image(bitmap_handle,nullptr);UINT count=0,bytes=0;Gdiplus::GetImageEncodersSize(&count,&bytes);std::vector<unsigned char> storage(bytes);const auto encoders=reinterpret_cast<Gdiplus::ImageCodecInfo*>(storage.data());if(bytes&&Gdiplus::GetImageEncoders(count,bytes,encoders)==Gdiplus::Ok)for(UINT i=0;i<count;++i)if(wcscmp(encoders[i].MimeType,L"image/png")==0){saved=image.Save(path.c_str(),&encoders[i].Clsid)==Gdiplus::Ok;break;}}
    DeleteObject(bitmap_handle);DeleteDC(memory);ReleaseDC(h,dc);if(!saved)return false;
    Gdiplus::Bitmap bitmap(path.c_str());if(bitmap.GetLastStatus()!=Gdiplus::Ok)return false;Gdiplus::Color first{},pixel{};bitmap.GetPixel(0,0,&first);
    for(UINT y=0;y<bitmap.GetHeight();y+=13)for(UINT x=0;x<bitmap.GetWidth();x+=13){bitmap.GetPixel(x,y,&pixel);if(pixel.GetValue()!=first.GetValue())return true;}return false;
}
